<?php require 'config/bootstrap.php';$products=$pdo->query("SELECT p.*,u.nama,u.fakultas,u.prodi FROM produk p JOIN users u ON u.id=p.user_id ORDER BY p.created_at DESC")->fetchAll();headpage('Katalog');?><section class="hero mb-4"><h1>Jual Beli Produk & Jasa Buatan Anak USU!</h1><p>Telusuri katalog, pesan langsung ke penjual, atau daftarkan usahamu.</p><a class="btn btn-green" href="register.php">Mulai Berjualan</a></section><h2>Untuk Anda</h2><div class="row g-3"><?php foreach($products as $p):?><div class="col-md-4"><article class="card h-100"><?php if($p['gambar_produk']):?><img src="<?=e($p['gambar_produk'])?>" alt=""><?php endif;?><div class="card-body"><h5><?=e($p['nama_produk'])?></h5><span class="badge bg-secondary"><?=e(str_replace('_',' ',$p['status_produk']))?></span><p><?=e(mb_strimwidth($p['deskripsi_produk'],0,130,'…'))?></p><p><?=e($p['nama'])?> · <?=e($p['fakultas'])?></p><a class="btn btn-green" href="product.php?id=<?=(int)$p['id']?>">Detail</a></div></article></div><?php endforeach;?><?php if(!$products):?><p>Belum ada produk yang dipublikasikan.</p><?php endif;?></div><?php footpage();?>
